import json
import pickle
from contextlib import asynccontextmanager
from typing import List

import pandas as pd
from fastapi import FastAPI, HTTPException
from pydantic import BaseModel

MODEL_PATH = '/app/models/best_model.pkl'
COMPARISON_PATH = '/app/output/model_comparison.json'
FEATURES = ['MedInc', 'HouseAge', 'AveRooms', 'AveBedrms', 'Population', 'AveOccup', 'Latitude', 'Longitude']

state = {}


@asynccontextmanager
async def lifespan(app):
    with open(MODEL_PATH, 'rb') as f:
        state['model'] = pickle.load(f)
    with open(COMPARISON_PATH) as f:
        state['name'] = json.load(f)['best_model_name']
    yield
    state.clear()


app = FastAPI(title='California Housing Price API', lifespan=lifespan)


class PredictRequest(BaseModel):
    features: List[float]


class PredictBatchRequest(BaseModel):
    features_list: List[List[float]]


@app.post('/predict')
def predict(req: PredictRequest):
    if len(req.features) != 8:
        raise HTTPException(status_code=422, detail='features must contain exactly 8 values')
    X = pd.DataFrame([req.features], columns=FEATURES)
    pred = float(state['model'].predict(X)[0])
    return {'prediction': pred, 'model_name': state['name']}


@app.get('/health')
def health():
    return {'status': 'healthy', 'model_loaded': 'model' in state}


@app.get('/model-info')
def model_info():
    return {
        'model_name': state['name'],
        'model_type': type(state['model']).__name__,
        'features_count': 8,
    }


@app.post('/predict-batch')
def predict_batch(req: PredictBatchRequest):
    for row in req.features_list:
        if len(row) != 8:
            raise HTTPException(status_code=422, detail='each inner list must contain exactly 8 values')
    if not req.features_list:
        return {'predictions': [], 'model_name': state['name'], 'count': 0}
    X = pd.DataFrame(req.features_list, columns=FEATURES)
    preds = [float(p) for p in state['model'].predict(X)]
    return {'predictions': preds, 'model_name': state['name'], 'count': len(preds)}
